macro_rules! deps {
    () => {
        Engine!();
    };
}

macro_rules! EncoderWriter {
    () => {
        deps!();
        # [doc = " A `Write` implementation that base64 encodes data before delegating to the wrapped writer."] # [doc = ""] # [doc = " Because base64 has special handling for the end of the input data (padding, etc), there's a"] # [doc = " `finish()` method on this type that encodes any leftover input bytes and adds padding if"] # [doc = " appropriate. It's called automatically when deallocated (see the `Drop` implementation), but"] # [doc = " any error that occurs when invoking the underlying writer will be suppressed. If you want to"] # [doc = " handle such errors, call `finish()` yourself."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::io::Write;"] # [doc = " use base64::engine::general_purpose;"] # [doc = ""] # [doc = " // use a vec as the simplest possible `Write` -- in real code this is probably a file, etc."] # [doc = " let mut enc = base64::write::EncoderWriter::new(Vec::new(), &general_purpose::STANDARD);"] # [doc = ""] # [doc = " // handle errors as you normally would"] # [doc = " enc.write_all(b\"asdf\").unwrap();"] # [doc = ""] # [doc = " // could leave this out to be called by Drop, if you don't care"] # [doc = " // about handling errors or getting the delegate writer back"] # [doc = " let delegate = enc.finish().unwrap();"] # [doc = ""] # [doc = " // base64 was written to the writer"] # [doc = " assert_eq!(b\"YXNkZg==\", &delegate[..]);"] # [doc = ""] # [doc = " ```"] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Calling `write()` (or related methods) or `finish()` after `finish()` has completed without"] # [doc = " error is invalid and will panic."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Base64 encoding itself does not generate errors, but errors from the wrapped writer will be"] # [doc = " returned as per the contract of `Write`."] # [doc = ""] # [doc = " # Performance"] # [doc = ""] # [doc = " It has some minor performance loss compared to encoding slices (a couple percent)."] # [doc = " It does not do any heap allocation."] # [doc = ""] # [doc = " # Limitations"] # [doc = ""] # [doc = " Owing to the specification of the `write` and `flush` methods on the `Write` trait and their"] # [doc = " implications for a buffering implementation, these methods may not behave as expected. In"] # [doc = " particular, calling `write_all` on this interface may fail with `io::ErrorKind::WriteZero`."] # [doc = " See the documentation of the `Write` trait implementation for further details."] pub struct EncoderWriter < 'e , E : Engine , W : io :: Write > { engine : & 'e E , # [doc = " Where encoded data is written to. It's an Option as it's None immediately before Drop is"] # [doc = " called so that `finish()` can return the underlying writer. None implies that `finish()` has"] # [doc = " been called successfully."] delegate : Option < W > , # [doc = " Holds a partial chunk, if any, after the last `write()`, so that we may then fill the chunk"] # [doc = " with the next `write()`, encode it, then proceed with the rest of the input normally."] extra_input : [u8 ; MIN_ENCODE_CHUNK_SIZE] , # [doc = " How much of `extra` is occupied, in `[0, MIN_ENCODE_CHUNK_SIZE]`."] extra_input_occupied_len : usize , # [doc = " Buffer to encode into. May hold leftover encoded bytes from a previous write call that the underlying writer"] # [doc = " did not write last time."] output : [u8 ; BUF_SIZE] , # [doc = " How much of `output` is occupied with encoded data that couldn't be written last time"] output_occupied_len : usize , # [doc = " panic safety: don't write again in destructor if writer panicked while we were writing to it"] panicked : bool , }
    };
}

EncoderWriter!()